sp_widget.client_script:
api.controller = function() {
  var c = this;
  c.submitting = false;
  c.errorMsg = '';
  c.form = {
    resolution_notes: '',
    resolution_code: ''
  };

  c.triggerUpload = function() {
    alert('Drag and drop files to attach. Max size: 10 MB per file.');
  };

  c.submitResolution = function() {
    c.errorMsg = '';
    if (!c.form.resolution_notes || !c.form.resolution_notes.trim()) {
      c.errorMsg = 'Resolution Notes are strictly required.';
      return;
    }
    c.submitting = true;
    c.data.action = 'resolve';
    c.data.form = c.form;

    c.server.update().then(function() {
      c.submitting = false;
      if (c.data.result && c.data.result.success) {
        // Return to My Assignments
        window.location.href = '?id=x_1956908_wareho_0_tech_dashboard';
      } else {
        c.errorMsg = (c.data.result && c.data.result.message) || 'Error resolving exception.';
      }
    });
  };
};

sp_widget.css:
.wei-resolve-wrapper {
  max-width: 600px;
  margin: 30px auto 60px;
  padding: 0 16px;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
}
.wei-resolve-card {
  background: #FFFFFF;
  border: 1px solid #E2E8F0;
  border-radius: 8px;
  padding: 32px 36px;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.04);
}
.wei-resolve-header {
  margin-bottom: 24px;
}
.wei-resolve-title {
  font-size: 20px;
  font-weight: 700;
  color: #0F172A;
  margin: 0 0 4px;
}
.wei-resolve-subtitle {
  font-size: 13px;
  color: #64748B;
  margin: 0;
}
.row-align {
  display: flex;
  align-items: center;
  gap: 20px;
  margin-bottom: 18px;
}
.wei-label-static {
  font-size: 13px;
  font-weight: 600;
  color: #475569;
  margin: 0;
}
.wei-static-val {
  font-size: 14px;
  font-weight: 700;
  color: #0F172A;
}
.wei-label {
  font-size: 13px;
  font-weight: 600;
  color: #334155;
  margin-bottom: 6px;
}
.wei-textarea, .wei-select {
  border: 1px solid #CBD5E1 !important;
  border-radius: 6px !important;
  font-size: 13px !important;
}
.wei-dropzone {
  border: 1.5px dashed #CBD5E1;
  border-radius: 6px;
  background: #F8FAFC;
  padding: 24px 16px;
  text-align: center;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
}
.wei-dropzone:hover {
  border-color: #1976D2;
  background: #F0F7FF;
}
.dropzone-icon { font-size: 16px; color: #64748B; }
.dropzone-text { font-size: 12px; color: #64748B; }
.wei-form-buttons {
  display: flex;
  gap: 12px;
  margin-top: 24px;
}
.btn-submit-resolve {
  background: #1976D2;
  border-color: #1976D2;
  font-size: 13px;
  font-weight: 600;
  padding: 8px 24px;
  border-radius: 6px;
}
.btn-cancel-resolve {
  font-size: 13px;
  font-weight: 500;
  padding: 8px 20px;
  border-radius: 6px;
  border: 1px solid #CBD5E1;
  color: #475569;
}

sp_widget.script:
(function() {
  var tableName = 'x_1956908_wareho_0_exception';
  var sysId = ($sp.getParameter('sys_id') || '').trim();

  // Role check: Technician and supervisor roles only
  var isTech = gs.hasRole('x_1956908_wareho_0.technician');
  var isSup = gs.hasRole('x_1956908_wareho_0.supervisor') || gs.hasRole('x_1956908_wareho_0.admin') || gs.hasRole('admin');

  data.allowed = isTech || isSup;
  if (!data.allowed) {
    data.error = 'Access denied';
    return;
  }

  if (sysId) {
    var gr = new GlideRecord(tableName);
    if (gr.get(sysId)) {
      data.record = {
        sys_id: gr.getUniqueValue(),
        number: gr.getValue('number') || ''
      };

      if (input && input.action === 'resolve' && input.form) {
        var notes = (input.form.resolution_notes || '').trim();
        var code = input.form.resolution_code || '';

        // Sets state = Pending Verification (maps to pending in dictionary)
        gr.setValue('status', 'pending');

        var combinedNotes = notes;
        if (code) {
          combinedNotes += '\n[Resolution Code: ' + code + ']';
        }
        gr.setValue('resolution_notes', combinedNotes);
        gr.work_notes = 'Resolution submitted by ' + gs.getUserDisplayName() + '. State updated to Pending Verification.';
        gr.update();

        data.result = { success: true };
      }
    }
  }
})();
